$_MODULE['<{retractationcommande}prestashop>pdf-accuse_11a3f4d6e53bd65481fadea719f7186d'] = 'Retouradres';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_afe72c2b21191da1897798ce03f6bb0a'] = 'Overeenkomstig artikel L221-21 van het Franse consumentenwetboek bevestigen wij de ontvangst van uw herroepingsverzoek';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_1d4a33337550b1d60f155dc7dca2ecef'] = 'Uw verzoek wordt beoordeeld door onze klantenservice (naleving van de wettelijke termijn, uitsluitingen van artikel L221-28 van het Franse consumentenwetboek). Voldoet het, dan ontvangt u de retourprocedure per e-mail. Stuur het product of de producten niet terug voordat u deze hebt ontvangen. De terugbetaling vindt uiterlijk 14 dagen na terugontvangst van de goederen of na ontvangst van het verzendbewijs plaats, via hetzelfde betaalmiddel als bij de bestelling (art. L221-24). De rechtstreekse kosten van terugzending blijven voor uw rekening (art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_08a4255076063ff093392602b74f2dde'] = 'Omdat uw bestelling op het moment van uw verzoek al was verzonden, kunt u het pakket bij aanbieding weigeren of, als u het ontvangt, de retourprocedure volgen die onze klantenservice u na beoordeling toestuurt (uitsluitingen van artikel L221-28 van het Franse consumentenwetboek). De terugbetaling vindt uiterlijk 14 dagen na terugontvangst van de goederen of na ontvangst van het bewijs van terugzending plaats, via hetzelfde betaalmiddel als bij de bestelling (art. L221-24). De rechtstreekse kosten van terugzending blijven voor uw rekening (art. L221-23).';
$_MODULE['<{retractationcommande}prestashop>pdf-accuse_ecd429447c2c5c11827567f6c066424e'] = 'Omdat uw bestelling op het moment van uw verzoek nog niet was verzonden, is een retourzending niet nodig. Na beoordeling door onze klantenservice (uitsluitingen van artikel L221-28 van het Franse consumentenwetboek) wordt de verzending geannuleerd en wordt het volledige betaalde bedrag u uiterlijk 14 dagen na uw verzoek terugbetaald, via hetzelfde betaalmiddel als bij de bestelling (art. L221-24).';
$_MODULE['<{retractationcommande}prestashop>formulaire_6fd32367e8a01032b6c24770df162923'] = 'Overeenkomstig de artikelen L221-18 en volgende van het Franse consumentenwetboek beschikt u over';
$_MODULE['<{retractationcommande}prestashop>formulaire_04f75f9992b78fd3affb67c8db773850'] = 'vanaf de dag na de levering om te herroepen, zonder opgave van redenen. Verstrijkt deze termijn op een zaterdag, zondag of feestdag, dan wordt hij verlengd tot de eerstvolgende werkdag.';
