$_MODULE['<{retractationcommande}prestashop>formulaire_c1ce181667f69ea149cb0a425ccdb21e'] = 'Geen van uw bestellingen komt op dit moment in aanmerking voor een retour (termijn verstreken of bestellingen niet van toepassing).';
$_MODULE['<{retractationcommande}prestashop>formulaire_24eabc929ddb3eb38fd6cf81b5ffa805'] = 'Voer het e-mailadres in dat u bij de bestelling hebt gebruikt en de referentie van de bestelling (die op uw bevestigingsmail staat).';
$_MODULE['<{retractationcommande}prestashop>formulaire_b414b1464d384d5b827c361fec76cc8f'] = 'Deze bestelling komt niet (meer) in aanmerking voor online herroeping: wettelijke termijn verstreken, verzoek al ingediend of bestelling niet van toepassing. Neem bij vragen contact op met onze klantenservice.';
$_MODULE['<{retractationcommande}prestashop>formulaire_dbad83ecebaf719a4dd60e45bbec0e03'] = 'Het herroepingsrecht geldt niet voor bepaalde overeenkomsten (art. L221-28 van het Franse consumentenwetboek: op maat gemaakte of gepersonaliseerde goederen, bederfelijke goederen, om hygiënische redenen ontzegelde goederen enz.). Na indiening wordt uw verzoek beoordeeld door onze klantenservice, die u de retourprocedure toestuurt. De terugbetaling vindt uiterlijk 14 dagen na terugontvangst van de goederen of na ontvangst van het verzendbewijs plaats, via hetzelfde betaalmiddel. De kosten van terugzending blijven voor uw rekening.';
$_MODULE['<{retractationcommande}prestashop>modal_30e7d78f70861e0332aa4cbb81a2fcd3'] = 'Retour mogelijk';
