$_MODULE['<{retractationcommande}prestashop>modal_217c9acbe7666448db6b898ca2ab6bef'] = 'Retouraanvraag bevestigen';
$_MODULE['<{retractationcommande}prestashop>modal_810a3d382ec684c35146d332e396e1c1'] = 'Door te bevestigen wordt uw herroepingsverzoek doorgestuurd naar onze klantenservice en ontvangt u per e-mail een ontvangstbevestiging met een pdf-exemplaar (art. L221-21 van het Franse consumentenwetboek). Na de beoordeling (wettelijke termijn, uitsluitingen van art. L221-28) ontvangt u de retourprocedure — stuur de producten niet terug voordat u deze hebt ontvangen. De terugbetaling vindt uiterlijk 14 dagen na terugontvangst van de goederen of na ontvangst van het verzendbewijs plaats (inclusief leveringskosten bij volledige herroeping, anders naar rato). De kosten van terugzending blijven voor uw rekening.';
$_MODULE['<{retractationcommande}prestashop>modal_abeaaec30c11df72742faf07dc857200'] = 'Door te bevestigen wordt uw herroepingsverzoek doorgestuurd naar onze klantenservice en ontvangt u per e-mail een ontvangstbevestiging met een pdf-exemplaar (art. L221-21 van het Franse consumentenwetboek). Omdat uw bestelling al is verzonden, kunt u het pakket bij aanbieding weigeren; ontvangt u het toch, open het dan niet en volg de retourprocedure die onze klantenservice u toestuurt. De terugbetaling vindt uiterlijk 14 dagen na terugontvangst van de goederen of na ontvangst van het bewijs van terugzending plaats. De kosten van terugzending blijven voor uw rekening.';
$_MODULE['<{retractationcommande}prestashop>modal_ad52dcb5592e9f635028ab04aaf1fcec'] = 'Door te bevestigen wordt uw herroepingsverzoek doorgestuurd naar onze klantenservice en ontvangt u per e-mail een ontvangstbevestiging met een pdf-exemplaar (art. L221-21 van het Franse consumentenwetboek). Omdat uw bestelling nog niet is verzonden, is een retourzending niet nodig: na beoordeling (uitsluitingen van art. L221-28) wordt de verzending geannuleerd en wordt het volledige betaalde bedrag u uiterlijk 14 dagen na uw verzoek terugbetaald, via hetzelfde betaalmiddel.';
$_MODULE['<{retractationcommande}prestashop>modal_c729999c38ef8dd3345cdcab0b29495a'] = 'Door te bevestigen wordt uw retouraanvraag doorgestuurd naar onze klantenservice, die deze toetst aan onze retourvoorwaarden en u de te volgen procedure meedeelt. Stuur de producten niet terug voordat u deze hebt ontvangen.';
$_MODULE['<{retractationcommande}prestashop>order-detail_5d6cad579ad55412b4c2f0e3e412a87a'] = 'U beschikt over een wettelijke termijn van 14 dagen om te herroepen';
